import threading


def reproduce(connect, service):
    # Race many concurrent withdrawals against the same account.
    # Start balance is fixed at 1000, each withdrawal is 600, so at most
    # one can legitimately succeed and the balance can never go below 0.
    for account_id in range(1, 11):
        try:
            with connect() as conn:
                conn.execute(
                    "UPDATE accounts SET balance = 1000 WHERE id = %s",
                    (account_id,),
                )
        except Exception:
            continue

        n = 12
        barrier = threading.Barrier(n)
        outcomes = []
        lock = threading.Lock()

        def worker():
            try:
                with connect() as conn:
                    try:
                        barrier.wait(timeout=15)
                    except Exception:
                        pass
                    try:
                        service.withdraw(conn, account_id, 600)
                        with lock:
                            outcomes.append("ok")
                    except service.InsufficientFunds:
                        with lock:
                            outcomes.append("insufficient")
                    except Exception as exc:  # expected service/psycopg errors only noted
                        with lock:
                            outcomes.append(f"other:{exc!r}")
            except Exception as exc:
                with lock:
                    outcomes.append(f"conn:{exc!r}")

        threads = [threading.Thread(target=worker) for _ in range(n)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=20)

        try:
            with connect() as conn:
                row = conn.execute(
                    "SELECT balance FROM accounts WHERE id = %s",
                    (account_id,),
                ).fetchone()
        except Exception:
            continue
        if row is None:
            continue
        final = row[0]
        ok_count = outcomes.count("ok")
        if final < 0:
            return (
                f"overdraft: account {account_id} balance {final} after "
                f"{ok_count} concurrent withdrawals of 600 from 1000"
            )
        if ok_count > 1:
            return (
                f"overdraft: account {account_id} allowed {ok_count} "
                f"withdrawals of 600 from 1000, balance {final}"
            )
    return None
